-- Every loaded norm: items, references, items whose parent is missing, references to missing items. Read only.
SELECT A.AGREEMENT_ID, (SELECT COUNT(*) FROM AGREEMENT_ITEM I WHERE I.AGREEMENT_ID=A.AGREEMENT_ID) ITEMS,
 (SELECT COUNT(*) FROM AGREEMENT_ASSOC S WHERE S.AGREEMENT_ID=A.AGREEMENT_ID) ASSOCS,
 (SELECT COUNT(*) FROM AGREEMENT_ITEM I WHERE I.AGREEMENT_ID=A.AGREEMENT_ID AND I.PARENT_ITEM_SEQ_ID IS NOT NULL AND NOT EXISTS (SELECT 1 FROM AGREEMENT_ITEM P WHERE P.AGREEMENT_ID=I.AGREEMENT_ID AND P.AGREEMENT_ITEM_SEQ_ID=I.PARENT_ITEM_SEQ_ID)) ORPHANS,
 (SELECT COUNT(*) FROM AGREEMENT_ASSOC S WHERE S.AGREEMENT_ID=A.AGREEMENT_ID AND S.TO_AGREEMENT_ITEM_SEQ_ID IS NOT NULL AND NOT EXISTS (SELECT 1 FROM AGREEMENT_ITEM P WHERE P.AGREEMENT_ID=S.TO_AGREEMENT_ID AND P.AGREEMENT_ITEM_SEQ_ID=S.TO_AGREEMENT_ITEM_SEQ_ID)) DANGLING
FROM AGREEMENT A WHERE A.AGREEMENT_TYPE_ENUM_ID IN ('AgrLegislation', 'AgrStandard') AND A.AGREEMENT_ID NOT LIKE 'STUB-%'
